    // On Linux, set via: export MY_FLAG=""
    // .NET 9 breaking change: empty env vars are no longer treated as unset.
    // Use a missing-check that distinguishes "not set" from "explicitly empty".
    var val = Environment.GetEnvironmentVariable("MY_FLAG");
    if (val is null && !IsEnvironmentVariableDefined("MY_FLAG"))
    {
        Console.WriteLine("MY_FLAG not set, using default");
    }
}

static bool IsEnvironmentVariableDefined(string name)
{
    // In .NET 9, GetEnvironmentVariable returns "" for empty vars (previously null).
    // A true "not set" variable still returns null.
    return Environment.GetEnvironmentVariable(name) is not null;
}

